/** Routes tagged `pay · contracts`. */
export class PayContractsResource extends Resource {
  /**
   * Inclui um item medível no contrato.
   *
   * O item tem descrição, unidade e preço unitário (até 4 casas) e passa a
   * poder entrar nas linhas dos boletins de medição.
   *
   * `POST /v1/pay/contracts/{id}/items`
   *
   * @param id Contrato
   * @param body Request body.
   * @param options Per-call overrides.
   */
  addItem(id: string, body: S.ContractItemCreateBody, options?: RequestOptions): Promise<S.ContractItemDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/items`, body, options });
  }

  /**
   * Aplica o reajuste de um aniversário que já chegou.
   *
   * Sem as taxas da janela o reajuste fica pendente e a emissão segue com o
   * valor antigo até a tabela ser completada.
   *
   * `POST /v1/pay/contracts/{id}/readjust`
   *
   * @param id Contrato
   * @param body Request body.
   * @param options Per-call overrides.
   */
  applyReadjust(id: string, body: S.ContractReadjustApplyBody, options?: RequestOptions): Promise<S.ContractReadjustResultDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/readjust`, body, options });
  }

  /**
   * Aprova o boletim: congela o preço de cada linha e o total.
   *
   * Pede uma permissão própria, separada de editar.
   *
   * `POST /v1/pay/contracts/{id}/measurements/{measurement_id}/approve`
   *
   * @param id Contrato
   * @param measurementId Boletim
   * @param options Per-call overrides.
   */
  approveMeasurement(id: string, measurementId: string, options?: RequestOptions): Promise<S.MeasurementDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/measurements/${seg(measurementId)}/approve`, options });
  }

  /**
   * Cria o contrato de uma assinatura.
   *
   * Uma assinatura tem no máximo um contrato. Plano fixo exige valor; plano
   * apurado não aceita valor. O valor do contrato substitui o do plano a partir
   * do próximo ciclo emitido.
   *
   * `POST /v1/pay/contracts`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  create(body: S.ContractCreateBody, options?: RequestOptions): Promise<S.ContractDetailDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts`, body, options });
  }

  /**
   * Abre o boletim de um mês (um por mês), em rascunho.
   *
   * As linhas dizem item e quantidade medida. Mês que já tem boletim responde
   * `409`; enquanto em rascunho, o boletim pode ser trocado inteiro.
   *
   * `POST /v1/pay/contracts/{id}/measurements`
   *
   * @param id Contrato
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createMeasurement(id: string, body: S.MeasurementCreateBody, options?: RequestOptions): Promise<S.MeasurementDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/measurements`, body, options });
  }

  /**
   * Um boletim com as linhas e o total.
   *
   * Em rascunho, o preço de cada linha é o atual do item; depois da aprovação,
   * é o que ficou congelado nela.
   *
   * `GET /v1/pay/contracts/{id}/measurements/{measurement_id}`
   *
   * @param id Contrato
   * @param measurementId Boletim
   * @param options Per-call overrides.
   */
  getMeasurement(id: string, measurementId: string, options?: RequestOptions): Promise<S.MeasurementDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/contracts/${seg(id)}/measurements/${seg(measurementId)}`, options });
  }

  /**
   * Um contrato com itens e os últimos eventos.
   *
   * Traz os termos vigentes, os itens medíveis e o histórico mais recente.
   * Contrato de organização fora do alcance do chamador responde `404`, como
   * se não existisse.
   *
   * `GET /v1/pay/contracts/{id}`
   *
   * @param id Contrato
   * @param options Per-call overrides.
   */
  getOne(id: string, options?: RequestOptions): Promise<S.ContractDetailDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/contracts/${seg(id)}`, options });
  }

  /**
   * Contratos das organizações do escopo, do mais novo para o mais antigo.
   *
   * Filtra por organização ou por assinatura e pagina por cursor
   * (`page_token`). Sem `organization_id`, traz todas as organizações que o
   * chamador alcança.
   *
   * `GET /v1/pay/contracts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: PayContractsListQuery, options?: RequestOptions): Promise<S.ContractPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/contracts`, query, options });
  }

  /**
   * Iterates every item of `list`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/contracts`
   */
  listAll(query?: PayContractsListQuery, options?: RequestOptions): Paginator<NonNullable<S.ContractPageDto["items"]>[number], S.ContractPageDto> {
    return new Paginator((page_token) => this.list({ ...query, page_token } as PayContractsListQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Boletins de medição do contrato, sem as linhas.
   *
   * Um boletim por mês medido. As linhas e o total de cada um vêm no detalhe
   * do boletim.
   *
   * `GET /v1/pay/contracts/{id}/measurements`
   *
   * @param id Contrato
   * @param options Per-call overrides.
   */
  listMeasurements(id: string, options?: RequestOptions): Promise<S.MeasurementListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/contracts/${seg(id)}/measurements`, options });
  }

  /**
   * Meses gravados de um índice (IPCA, IGP-M ou INPC) num intervalo.
   *
   * A tabela é do tenant: quem administra grava a variação mensal publicada.
   *
   * `GET /v1/pay/index-rates`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listRates(query: PayContractsListRatesQuery, options?: RequestOptions): Promise<S.IndexRateListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/index-rates`, query, options });
  }

  /**
   * Registra a não renovação do contrato.
   *
   * Dentro do aviso prévio o contrato acaba no fim do termo corrente; fora
   * dele, no fim do termo seguinte.
   *
   * `POST /v1/pay/contracts/{id}/non-renewal`
   *
   * @param id Contrato
   * @param options Per-call overrides.
   */
  nonRenewal(id: string, options?: RequestOptions): Promise<S.ContractDetailDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/non-renewal`, options });
  }

  /**
   * Calcula o reajuste do próximo aniversário sem gravar nada.
   *
   * `missing` lista os meses da janela que faltam na tabela do índice.
   *
   * `POST /v1/pay/contracts/{id}/readjust/preview`
   *
   * @param id Contrato
   * @param options Per-call overrides.
   */
  previewReadjust(id: string, options?: RequestOptions): Promise<S.ContractReadjustPreviewDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/contracts/${seg(id)}/readjust/preview`, options });
  }

  /**
   * Grava meses de um índice de reajuste (IPCA, IGP-M ou INPC).
   *
   * Mês repetido troca o valor. O reajuste que estava pendente por falta de
   * taxa não se aplica sozinho: entra no próximo ciclo ou ao reajustar à mão.
   *
   * `PUT /v1/pay/index-rates`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  putRates(body: S.IndexRatesBody, options?: RequestOptions): Promise<S.IndexRateListDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/index-rates`, body, options });
  }

  /**
   * Altera ou inativa um item do contrato.
   *
   * Boletim já aprovado guarda o preço que valia na aprovação; o rascunho usa
   * o preço vivo do item, então a mudança alcança os rascunhos abertos.
   *
   * `PATCH /v1/pay/contracts/{id}/items/{item_id}`
   *
   * @param id Contrato
   * @param itemId Item
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateItem(id: string, itemId: string, body: S.ContractItemUpdateBody, options?: RequestOptions): Promise<S.ContractItemDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/contracts/${seg(id)}/items/${seg(itemId)}`, body, options });
  }

  /**
   * Troca a observação e as linhas de um boletim em rascunho.
   *
   * As linhas enviadas substituem todas as anteriores. Boletim já aprovado não
   * muda e responde `412`.
   *
   * `PUT /v1/pay/contracts/{id}/measurements/{measurement_id}`
   *
   * @param id Contrato
   * @param measurementId Boletim
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateMeasurement(id: string, measurementId: string, body: S.MeasurementUpdateBody, options?: RequestOptions): Promise<S.MeasurementDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/contracts/${seg(id)}/measurements/${seg(measurementId)}`, body, options });
  }

  /**
   * Troca os termos do contrato (aditivo).
   *
   * Vale a partir do próximo ciclo emitido; ciclo já emitido não muda. Número
   * de contrato repetido ou duas alterações ao mesmo tempo respondem `409`.
   *
   * `PUT /v1/pay/contracts/{id}`
   *
   * @param id Contrato
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateOne(id: string, body: S.ContractUpdateBody, options?: RequestOptions): Promise<S.ContractDetailDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/contracts/${seg(id)}`, body, options });
  }
}

