/** Routes tagged `pay · debts`. */
export class PayDebtsResource extends Resource {
  /**
   * Cancela um contrato sem título vivo (nenhum gerado, ou todos cancelados).
   *
   * Com algum título vivo a resposta é 412: cancele os títulos em contas a
   * pagar antes. O contrato cancelado continua legível e sai da posição.
   *
   * `POST /v1/pay/debts/{id}/cancel`
   *
   * @param id Contrato de dívida
   * @param options Per-call overrides.
   */
  cancel(id: string, options?: RequestOptions): Promise<S.DebtContractDetailDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/debts/${seg(id)}/cancel`, options });
  }

  /**
   * Cadastra um contrato e grava o cronograma (nenhum título nasce aqui).
   *
   * O cronograma sai dos termos (principal, taxa, sistema de amortização,
   * parcelas e datas) e fica gravado junto do contrato. Os títulos a pagar só
   * nascem depois, sob pedido, em `POST /v1/pay/debts/{id}/payables`.
   *
   * `POST /v1/pay/debts`
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `Idempotency-Key`.
   */
  create(body: S.DebtCreateBody, options?: RequestOptions & { headers?: { "Idempotency-Key"?: string } }): Promise<S.DebtContractDetailDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/debts`, body, options });
  }

  /**
   * Gera os títulos a pagar (amortização e juros) das parcelas que vencem até
   * `through`; parcela com título vivo fica como está, título cancelado é
   * substituído.
   *
   * Cada parcela gera dois títulos (amortização e juros) pelo mesmo caminho da
   * tela de contas a pagar: credor, categoria, período fechado e alçada. A
   * chave de idempotência é por parcela, então repetir o pedido ou retomar uma
   * geração interrompida devolve os títulos que já existem.
   *
   * `POST /v1/pay/debts/{id}/payables`
   *
   * @param id Contrato de dívida
   * @param body Request body.
   * @param options Per-call overrides.
   */
  generatePayables(id: string, body: S.DebtGenerateBody, options?: RequestOptions): Promise<S.DebtPayablesGeneratedDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/debts/${seg(id)}/payables`, body, options });
  }

  /**
   * Lê um contrato com as parcelas e a posição de hoje.
   *
   * A posição (saldo devedor, juros a vencer, atraso) é calculada na hora a
   * partir dos títulos. Contrato fora da vista da sessão responde 404.
   *
   * `GET /v1/pay/debts/{id}`
   *
   * @param id Contrato de dívida
   * @param options Per-call overrides.
   */
  getOne(id: string, options?: RequestOptions): Promise<S.DebtContractDetailDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/debts/${seg(id)}`, options });
  }

  /**
   * Lista os contratos da sessão (mais novos primeiro).
   *
   * Sessão presa a uma organização vê só os contratos dela. Os cancelados ficam
   * de fora, a menos que `include_cancelled` seja verdadeiro.
   *
   * `GET /v1/pay/debts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: PayDebtsListQuery, options?: RequestOptions): Promise<S.DebtContractPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/debts`, query, options });
  }

  /**
   * Iterates every item of `list`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/debts`
   */
  listAll(query?: PayDebtsListQuery, options?: RequestOptions): Paginator<NonNullable<S.DebtContractPageDto["items"]>[number], S.DebtContractPageDto> {
    return new Paginator((page_token) => this.list({ ...query, page_token } as PayDebtsListQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Posição consolidada de uma moeda: saldo devedor, custo médio ponderado da
   * dívida e, com o capital próprio informado, o WACC.
   *
   * Soma os contratos ativos da moeda pedida. O WACC só sai com `equity` e
   * `cost_of_equity_percent`; `tax_rate_percent` desconta o benefício fiscal dos
   * juros. Acima de 2000 contratos ativos a resposta é 412.
   *
   * `GET /v1/pay/debts/portfolio`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  portfolio(query?: PayDebtsPortfolioQuery, options?: RequestOptions): Promise<S.DebtPortfolioDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/debts/portfolio`, query, options });
  }

  /**
   * Cronograma de um contrato sem gravar nada.
   *
   * Usa as mesmas regras do cadastro, para conferir parcelas e juros antes de
   * criar o contrato. Taxa anual vira a mensal equivalente composta.
   *
   * `POST /v1/pay/debts/simulate`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  simulate(body: S.DebtSimulateBody, options?: RequestOptions): Promise<S.DebtScheduleDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/debts/simulate`, body, options });
  }

  /**
   * Troca o prazo (parcelas e primeiro vencimento) e refaz o cronograma com o
   * mesmo principal, taxa e sistema.
   *
   * Só antes do primeiro título gerado: depois dele a resposta é 412
   * (`debt_has_payables`). Contrato cancelado também é 412 (`debt_cancelled`).
   *
   * `PUT /v1/pay/debts/{id}/term`
   *
   * @param id Contrato de dívida
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateTerm(id: string, body: S.PayDebtTermInput, options?: RequestOptions): Promise<S.DebtContractDetailDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/debts/${seg(id)}/term`, body, options });
  }
}

