/** Routes tagged `pay · financial-accounts`. */
export class PayFinancialAccountsResource extends Resource {
  /**
   * Fecha uma conta gráfica (transição para status `closed`).
   *
   * Operação irreversível - o backend rejeita wallets ativas na conta.
   * Retorna `204 No Content` em sucesso.
   * Retorna `404` se a conta não existir ou não pertencer ao tenant.
   *
   * `DELETE /v1/pay/financial-accounts/{id}`
   *
   * @param id Conta gráfica
   * @param options Per-call overrides.
   */
  close(id: string, options?: RequestOptions): Promise<void> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/financial-accounts/${seg(id)}`, responseType: 'void', options });
  }

  /**
   * Cria uma nova conta gráfica financeira.
   *
   * Retorna `201 Created` com o `FinancialAccountDto`.
   * Retorna `409 Conflict` se viola unicidade de conta padrão.
   * tenant_id é injetado pelo gateway via `RequestContext` - nunca vem do body.
   *
   * `POST /v1/pay/financial-accounts`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  create(body: S.CreateFinancialAccountBody, options?: RequestOptions): Promise<S.FinancialAccountDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/financial-accounts`, body, options });
  }

  /**
   * Recupera uma conta gráfica pelo Snowflake.
   *
   * Retorna `200 OK` com `FinancialAccountDto`.
   * Retorna `404 Not Found` se não existir ou não pertencer ao tenant.
   * A validação de escopo multi-tenant é feita pelo backend - o `tenant_id`
   * no `RequestContext` garante isolamento.
   *
   * `GET /v1/pay/financial-accounts/{id}`
   *
   * @param id Conta gráfica
   * @param options Per-call overrides.
   */
  getOne(id: string, options?: RequestOptions): Promise<S.FinancialAccountDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-accounts/${seg(id)}`, options });
  }

  /**
   * Lista contas gráficas do tenant com paginação por cursor (keyset).
   *
   * Escopo do tenant é garantido pelo `RequestContext` - o backend filtra
   * automaticamente pelo `tenant_id` sem necessidade de parâmetro explícito.
   * Retorna `200 OK` com `FinancialAccountsListDto`.
   *
   * `GET /v1/pay/financial-accounts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: PayFinancialAccountsListQuery, options?: RequestOptions): Promise<S.FinancialAccountsListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-accounts`, query, options });
  }

  /**
   * Iterates every item of `list`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/financial-accounts`
   */
  listAll(query?: PayFinancialAccountsListQuery, options?: RequestOptions): Paginator<NonNullable<S.FinancialAccountsListDto["items"]>[number], S.FinancialAccountsListDto> {
    return new Paginator((page_token) => this.list({ ...query, page_token } as PayFinancialAccountsListQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Atualiza parcialmente uma conta gráfica (PATCH).
   *
   * Apenas `name` e `is_default` são mutáveis. Retorna `200 OK` com o
   * `FinancialAccountDto` atualizado. Retorna `404` se não encontrada.
   *
   * `PATCH /v1/pay/financial-accounts/{id}`
   *
   * @param id Conta gráfica
   * @param body Request body.
   * @param options Per-call overrides.
   */
  update(id: string, body: S.UpdateFinancialAccountBody, options?: RequestOptions): Promise<S.FinancialAccountDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/financial-accounts/${seg(id)}`, body, options });
  }
}

