/** Routes tagged `pay · financial-settings`. */
export class PayFinancialSettingsResource extends Resource {
  /**
   * Remove o desconto de um meio de pagamento.
   *
   * O meio deixa de ter desconto no escopo; a regra do tenant, se houver, volta
   * a valer para a organização.
   *
   * `DELETE /v1/pay/financial-settings/method-discounts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  deleteDiscount(query: PayFinancialSettingsDeleteDiscountQuery, options?: RequestOptions): Promise<S.DeleteMethodDiscountDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/financial-settings/method-discounts`, query, options });
  }

  /**
   * Remove a fixação de um adquirente.
   *
   * O método e a modalidade voltam a ser escolhidos pelo menor custo.
   *
   * `DELETE /v1/pay/financial-settings/acquirer-pins`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  deletePin(query: PayFinancialSettingsDeletePinQuery, options?: RequestOptions): Promise<S.DeleteAcquirerPinDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/financial-settings/acquirer-pins`, query, options });
  }

  /**
   * Consulta a Configuração financeira de atraso resolvida para o escopo
   * (org→tenant). `found = false` quando nenhum escopo tem configuração.
   * Permissão `pay.configuracoes.config-financeira.read` aplicada na borda.
   *
   * Devolve a configuração **já resolvida** para o escopo, aplicando a precedência
   * organização sobre tenant, para que o cliente não reimplemente a cascata.
   *
   * `found = false` significa que nenhum dos escopos tem configuração.
   *
   * `GET /v1/pay/financial-settings`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  get(query?: PayFinancialSettingsGetQuery, options?: RequestOptions): Promise<S.GetFinancialSettingsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings`, query, options });
  }

  /**
   * Lê a política de parcelamento do escopo e a que vale nas vendas.
   *
   * Sem política gravada o parcelamento fica desligado (só à vista): um lojista
   * que nunca configurou não passa a pagar a taxa de 12x sem saber.
   *
   * `GET /v1/pay/financial-settings/installments`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  getPolicy(query?: PayFinancialSettingsGetPolicyQuery, options?: RequestOptions): Promise<S.InstallmentPolicyViewDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings/installments`, query, options });
  }

  /**
   * Lista os adquirentes que o lojista pode escolher para o método, com a tarifa
   * de cada um - escolher adquirente é escolher custo, então o preço
   * vem junto. Permissão `pay.configuracoes.config-financeira.read`.
   *
   * Lista os adquirentes que o lojista pode escolher para aquele método de
   * pagamento, com a tarifa de cada um.
   *
   * O preço vem junto porque escolher adquirente é escolher custo, e uma lista sem
   * tarifa faria a escolha parecer indiferente. O filtro é o mesmo da emissão
   * (capacidade, moeda, método e dono da credencial): opção que apareceria aqui e
   * não seria escolhida na emissão é defeito, e já aconteceu.
   *
   * `GET /v1/pay/financial-settings/acquiring-options`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listAcquiringOptions(query: PayFinancialSettingsListAcquiringOptionsQuery, options?: RequestOptions): Promise<S.ListAcquiringOptionsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings/acquiring-options`, query, options });
  }

  /**
   * Lê o desconto por meio de pagamento do escopo e o que vale nas vendas.
   *
   * Uma regra por meio. Meio sem regra não tem desconto.
   *
   * `GET /v1/pay/financial-settings/method-discounts`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listDiscounts(query?: PayFinancialSettingsListDiscountsQuery, options?: RequestOptions): Promise<S.MethodDiscountsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings/method-discounts`, query, options });
  }

  /**
   * Lista os adquirentes fixados no escopo.
   *
   * Uma linha por método e modalidade. Sem fixação o motor escolhe pelo menor
   * custo.
   *
   * `GET /v1/pay/financial-settings/acquirer-pins`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPins(query?: PayFinancialSettingsListPinsQuery, options?: RequestOptions): Promise<S.AcquirerPinsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings/acquirer-pins`, query, options });
  }

  /**
   * Cota as opções de parcelamento de uma venda no cartão.
   *
   * Usa a mesma conta que a emissão refaz: teto efetivo, quem limitou, total e
   * valor de cada parcela, com o repasse da taxa quando a política manda.
   *
   * `GET /v1/pay/financial-settings/installments/quote`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  quote(query: PayFinancialSettingsQuoteQuery, options?: RequestOptions): Promise<S.InstallmentQuoteDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/financial-settings/installments/quote`, query, options });
  }

  /**
   * Grava (upsert) a Configuração financeira de atraso do escopo - override da
   * organização sobre o tenant. Permissão
   * `pay.configuracoes.config-financeira.manage` aplicada na borda. tenant_id injetado pelo gateway.
   *
   * Grava a configuração de atraso do escopo: multa, juros e carência aplicados a
   * título vencido.
   *
   * A organização sobrepõe o tenant. Gravar na organização não altera o padrão do
   * tenant, e é isso que permite uma filial ter política própria sem quebrar o resto
   * do grupo.
   *
   * `PUT /v1/pay/financial-settings`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  set(body: S.SetFinancialSettingsBody, options?: RequestOptions): Promise<S.FinancialSettingsDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/financial-settings`, body, options });
  }

  /**
   * Grava o desconto de um meio de pagamento.
   *
   * Tipos: percentual, a cada R$ X R$ Y off, ou valor fixo, com teto e compra
   * mínima opcionais, e a escolha de somar com o cupom ou valer o maior. A base
   * são os produtos (sem frete). Vale para as vendas novas.
   *
   * `PUT /v1/pay/financial-settings/method-discounts`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setDiscount(body: S.SetMethodDiscountBody, options?: RequestOptions): Promise<S.MethodDiscountsDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/financial-settings/method-discounts`, body, options });
  }

  /**
   * Fixa um adquirente para um método e modalidade.
   *
   * Modalidade `single` ou `installments` (esta só no cartão). A fixação vence
   * o menor custo.
   *
   * `PUT /v1/pay/financial-settings/acquirer-pins`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setPin(body: S.SetAcquirerPinBody, options?: RequestOptions): Promise<S.AcquirerPinDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/financial-settings/acquirer-pins`, body, options });
  }

  /**
   * Grava a política de parcelamento do escopo.
   *
   * Campos: ligado, teto de parcelas, valor mínimo por parcela e a partir de
   * qual parcela o comprador paga a taxa. Vale para as vendas novas.
   *
   * `PUT /v1/pay/financial-settings/installments`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setPolicy(body: S.SetInstallmentPolicyBody, options?: RequestOptions): Promise<S.InstallmentPolicyViewDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/financial-settings/installments`, body, options });
  }
}

