/** Routes tagged `pay · fixed-assets`. */
export class PayFixedAssetsResource extends Resource {
  /**
   * Cadastra um bem. Não lança a aquisição.
   *
   * Grava código, datas de aquisição e de início de uso, custo, residual, vida
   * útil em meses, as contas do bem, da depreciação acumulada e da despesa e o
   * centro de custo. A depreciação começa no mês do início de uso.
   *
   * `POST /v1/pay/fixed-assets`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  create(body: S.FixedAssetCreateBody, options?: RequestOptions): Promise<S.FixedAssetDetailDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/fixed-assets`, body, options });
  }

  /**
   * Apaga um bem que ainda não tem mês lançado.
   *
   * Bem com qualquer mês lançado não apaga: baixe-o.
   *
   * `DELETE /v1/pay/fixed-assets/{id}`
   *
   * @param id Bem
   * @param options Per-call overrides.
   */
  deleteOne(id: string, options?: RequestOptions): Promise<S.FixedAssetDeletedDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/fixed-assets/${seg(id)}`, options });
  }

  /**
   * Baixa um bem: lança os meses que faltam e leva o valor contábil restante
   * para a conta de despesa informada.
   *
   * O bem passa a baixado e não deprecia mais. O lançamento da baixa sai na data
   * informada.
   *
   * `POST /v1/pay/fixed-assets/{id}/dispose`
   *
   * @param id Bem
   * @param body Request body.
   * @param options Per-call overrides.
   */
  dispose(id: string, body: S.FixedAssetDisposeBody, options?: RequestOptions): Promise<S.FixedAssetDisposeDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/fixed-assets/${seg(id)}/dispose`, body, options });
  }

  /**
   * Um bem com os meses lançados.
   *
   * Cada mês lançado traz o valor depreciado e o lançamento contábil que o
   * gravou.
   *
   * `GET /v1/pay/fixed-assets/{id}`
   *
   * @param id Bem
   * @param options Per-call overrides.
   */
  getOne(id: string, options?: RequestOptions): Promise<S.FixedAssetDetailDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/fixed-assets/${seg(id)}`, options });
  }

  /**
   * Lista os bens, mais novos primeiro.
   *
   * Paginado por cursor; filtra por situação (ativo ou baixado) e pela
   * organização, só ela ou a subárvore. Cada bem traz a depreciação lançada até
   * agora.
   *
   * `GET /v1/pay/fixed-assets`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: PayFixedAssetsListQuery, options?: RequestOptions): Promise<S.FixedAssetListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/fixed-assets`, query, options });
  }

  /**
   * Iterates every item of `list`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/fixed-assets`
   */
  listAll(query?: PayFixedAssetsListQuery, options?: RequestOptions): Paginator<NonNullable<S.FixedAssetListDto["items"]>[number], S.FixedAssetListDto> {
    return new Paginator((page_token) => this.list({ ...query, page_token } as PayFixedAssetsListQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Lança a depreciação pendente de todos os bens ativos até o mês pedido.
   * Repetir não duplica; período fechado vira `skipped`.
   *
   * Devolve os meses lançados, os pulados com o motivo e a soma. Quando o teto
   * da rodada para antes do fim, `more_pending` vem verdadeiro: rode de novo.
   *
   * `POST /v1/pay/fixed-assets/depreciation-runs`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  runDepreciation(body: S.FixedAssetRunBody, options?: RequestOptions): Promise<S.FixedAssetRunDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/fixed-assets/depreciation-runs`, body, options });
  }

  /**
   * Edita um bem. Cronograma só antes do primeiro mês lançado.
   *
   * Campo ausente fica como está. Nome e código mudam sempre; datas, custo,
   * residual, vida útil e contas só antes do primeiro mês lançado.
   *
   * `PATCH /v1/pay/fixed-assets/{id}`
   *
   * @param id Bem
   * @param body Request body.
   * @param options Per-call overrides.
   */
  update(id: string, body: S.FixedAssetUpdateBody, options?: RequestOptions): Promise<S.FixedAssetDetailDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/fixed-assets/${seg(id)}`, body, options });
  }
}

