/** Routes tagged `pay · ledger`. */
export class PayLedgerResource extends Resource {
  /**
   * Detalhe completo de uma operação - todas as pernas (inclui wallets externas).
   *
   * Devolve a operação com **todas as pernas**, inclusive as de carteiras externas.
   *
   * É a visão que fecha: em partidas dobradas, uma operação só é conferível quando
   * todas as pernas estão à vista, e esconder a perna externa faria a soma parecer
   * errada sem que houvesse erro.
   *
   * `GET /v1/pay/operations/{id}`
   *
   * @param id ID da operação
   * @param options Per-call overrides.
   */
  getOperation(id: string, options?: RequestOptions): Promise<S.FullOperationDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/operations/${seg(id)}`, options });
  }

  /**
   * Lista as operações financeiras do tenant com paginação por cursor e filtros.
   *
   * Fonte direta (tabela `pay_financial_operations`) - não reconstrói de extratos,
   * então inclui operações cujas pernas caem só em wallets externas. Ordem
   * decrescente por id (mais recentes primeiro). Filtros opcionais: organização
   * (as operações de escopo tenant - org `NULL`, ex. liquidações de PSP - sempre
   * entram), carteira, pessoa, adquirente, tipo e intervalo de datas. Cada item
   * traz agregados de exibição (valor movimentado, moeda, nº de pernas).
   * Retorna `200 OK`.
   *
   * `GET /v1/pay/operations`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listOperations(query?: PayLedgerListOperationsQuery, options?: RequestOptions): Promise<S.OperationsListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/operations`, query, options });
  }

  /**
   * Iterates every item of `listOperations`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/operations`
   */
  listOperationsAll(query?: PayLedgerListOperationsQuery, options?: RequestOptions): Paginator<NonNullable<S.OperationsListDto["items"]>[number], S.OperationsListDto> {
    return new Paginator((page_token) => this.listOperations({ ...query, page_token } as PayLedgerListOperationsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Lança uma operação financeira no ledger de dupla entrada.
   *
   * Retorna `201 Created` com o `FinancialOperationDto`, criado agora ou já
   * lançado pela mesma `idempotency_key`. Retorna `412 Precondition Failed` em
   * saldo insuficiente ou transição de estado inválida e `422` se as entradas
   * não somam zero.
   * tenant_id é injetado pelo gateway via `RequestContext`, nunca vem do body.
   *
   * `POST /v1/pay/operations`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  postOperation(body: S.PostOperationBody, options?: RequestOptions): Promise<S.FinancialOperationDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/operations`, body, options });
  }

  /**
   * Estorna uma operação financeira existente.
   *
   * Cria uma nova `FinancialOperation` com entradas invertidas (créditos viram
   * débitos e vice-versa). A operação original deve estar em status `success`.
   * Retorna `201 Created` com o `FinancialOperationDto` do estorno.
   * Retorna `404` se a operação original não existir.
   * Retorna `412` se a operação não estiver em `success`.
   *
   * `POST /v1/pay/operations/{id}/reverse`
   *
   * @param id Operação original
   * @param body Request body.
   * @param options Per-call overrides.
   */
  reverseOperation(id: string, body: S.ReverseOperationBody, options?: RequestOptions): Promise<S.FinancialOperationDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/operations/${seg(id)}/reverse`, body, options });
  }

  /**
   * Retorna o total de entradas, saídas e saldo líquido por moeda no tenant.
   *
   * Visão administrativa - mostra a posição agregada de todas as wallets do
   * tenant agrupada por moeda ISO 4217. Retorna `200 OK` com `SystemTotalsDto`.
   *
   * `GET /v1/pay/system-totals`
   *
   * @param options Per-call overrides.
   */
  systemTotals(options?: RequestOptions): Promise<S.SystemTotalsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/system-totals`, options });
  }

  /**
   * Retorna o extrato (lançamentos com saldo corrente) de uma wallet, paginado
   * por cursor.
   *
   * Linhas são retornadas em ordem decrescente de `id` (mais recentes primeiro);
   * o cursor avança para o passado. `running_balance` em cada linha representa o
   * saldo acumulado calculado via window function pelo backend - independe da
   * página. Retorna `200 OK` com `StatementResponseDto` (`next_page_token` vazio
   * = última página). Retorna `404` se a wallet não existir ou não pertencer ao
   * tenant.
   *
   * `GET /v1/pay/wallets/{wallet_id}/statement`
   *
   * @param walletId Wallet
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  walletStatement(walletId: string, query?: PayLedgerWalletStatementQuery, options?: RequestOptions): Promise<S.StatementResponseDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/wallets/${seg(walletId)}/statement`, query, options });
  }

  /**
   * Iterates every item of `walletStatement`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/wallets/{wallet_id}/statement`
   */
  walletStatementAll(walletId: string, query?: PayLedgerWalletStatementQuery, options?: RequestOptions): Paginator<NonNullable<S.StatementResponseDto["lines"]>[number], S.StatementResponseDto> {
    return new Paginator((page_token) => this.walletStatement(walletId, { ...query, page_token } as PayLedgerWalletStatementQuery, options), "lines", query?.page_token ?? undefined);
  }
}

