/** Routes tagged `pay · portal`. */
export class PayPortalResource extends Resource {
  /**
   * Um cartão **novo** passa a pagar os próximos ciclos.
   *
   * 🚨 **O PAN não passa por aqui**: o que chega é o token de uso
   * único criado no navegador com a chave de `GET.../card-key`.
   *
   * ⚠️ **Guardar não é apontar.** Cartão cobrável: guarda e reaponta a
   * assinatura, numa operação só - guardar sem apontar deixaria o assinante com
   * um cartão novo na conta e a mensalidade ainda saindo do antigo. Cartão que
   * voltou com desafio: guarda, devolve o `client_secret` e **não** reaponta; a
   * página completa o desafio e chama `PUT.../card` com o `saved_card_id`.
   *
   * `POST /v1/pay/public/portal/subscriptions/{id}/cards` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  addPortalSubscriptionCard(id: string, body: S.PortalNewCardBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalNewCardDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/cards`, body, auth: false, options });
  }

  /**
   * Fecha a sessão do portal. **Sem sessão de operador**: o portão é o token.
   *
   * Sair duas vezes devolve `200` com `closed = false`, e token inexistente
   * devolve o mesmo corpo: distinguir os casos entregaria a quem sonda que
   * aquele token um dia existiu (T10).
   *
   * `POST /v1/pay/public/portal/logout` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  closePortalSession(body: S.ClosePortalSessionBody, options?: RequestOptions): Promise<S.ClosedPortalSessionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/logout`, body, auth: false, options });
  }

  /**
   * Passo 2: o código confere e a sessão nasce, com escopo `manage`.
   *
   * ⚠️ **Escopo cheio, igual ao do handoff.** Um portal que mostra o cancelamento
   * e não deixa cancelar devolveria o assinante ao telefone do lojista, que é o
   * que esta porta existe para evitar. Trocar o canal de recuperação continua
   * pedindo o código do, mandado ao canal **antigo**: entrar por posse
   * não é poder mudar de dono.
   *
   * `POST /v1/pay/public/portal/access/verify` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  confirmPortalAccess(body: S.ConfirmPortalAccessBody, options?: RequestOptions): Promise<S.PortalSessionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/access/verify`, body, auth: false, options });
  }

  /**
   * Passo 2: o código confere, o canal troca e o endereço **antigo** é avisado.
   *
   * ⚠️ **Um motivo só para todo desfecho negativo do código** (`challenge_failed`):
   * errado, vencido, já usado, de outra sessão, de outro canal ou emitido para
   * outro valor. Separar "vencido" de "errado" conta a quem chuta que aquele
   * código existiu.
   *
   * `PUT /v1/pay/public/portal/contact` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  confirmPortalContactChange(body: S.ConfirmPortalContactBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<void> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/public/portal/contact`, body, responseType: 'void', auth: false, options });
  }

  /**
   * Troca o bilhete pela sessão do portal. **Servidor-a-servidor**.
   *
   * ⚠️ O bilhete vale **uma vez** e por 60 segundos. Trocar duas vezes é recusa,
   * não retentativa: um endereço que continua abrindo a conta de alguém depois de
   * encaminhado é o modelo de ameaça inteiro num objeto só.
   *
   * `POST /v1/pay/portal/handoff/{ticket}`
   *
   * @param ticket Bilhete opaco de uso único
   * @param options Per-call overrides.
   */
  exchangePortalTicket(ticket: string, options?: RequestOptions): Promise<S.PortalSessionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/portal/handoff/${seg(ticket)}`, options });
  }

  /**
   * A conta que a sessão do portal abre.
   *
   * Cadastro, assinaturas e cartões numa resposta só, porque é assim que a
   * primeira tela do portal os mostra: três rotas fariam a página emitir três
   * requisições com o mesmo token e falhar pela metade quando uma delas caísse.
   *
   * 🚨 **A pessoa sai da sessão, nunca do pedido.** Não existe `person_id` aqui,
   * e a ausência é o controle: com ele, qualquer sessão válida leria a conta de
   * qualquer assinante do tenant (ameaça `T5`).
   *
   * `GET /v1/pay/public/portal/account` (public route, sent without credentials)
   *
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  getPortalAccount(options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalAccountDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/public/portal/account`, auth: false, options });
  }

  /**
   * Lê o opt-in do portal deste tenant.
   *
   * Tenant que nunca ligou o portal não tem linha gravada e a resposta é
   * `is_enabled = false` com `enabled_at` nulo: a tela do lojista mostra o
   * desligado sem precisar tratar 404, e nenhum bilhete é emitido enquanto isso.
   *
   * `GET /v1/pay/portal/settings`
   *
   * @param options Per-call overrides.
   */
  getPortalSettings(options?: RequestOptions): Promise<S.PortalSettingsDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/portal/settings`, options });
  }

  /**
   * Emite o desafio de prova de trabalho da entrada do portal. **Sem sessão.**
   *
   * A porta do assinante é anônima por construção: qualquer pessoa
   * digita um e-mail e a plataforma manda um código para o endereço do cadastro.
   * Sem custo do lado de fora, uma lista de endereços vira uma varredura que faz
   * a plataforma mandar e-mail para gente que nunca pediu nada.
   *
   * 🚨 **O escopo é a rota, e não um campo do corpo.** Desafio emitido aqui só
   * se gasta aqui, e o emitido no checkout só lá: sem isso, a defesa mediria o
   * custo da porta errada.
   *
   * `POST /v1/pay/public/portal/challenge` (public route, sent without credentials)
   *
   * @param options Per-call overrides.
   */
  issuePortalPowChallenge(options?: RequestOptions): Promise<S.PowChallengeDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/challenge`, auth: false, options });
  }

  /**
   * Emite o bilhete que abre o portal de **uma** pessoa.
   *
   * 🚨 **Portal desligado e pessoa de outro tenant devolvem a MESMA recusa.**
   * Dizer "o portal está desligado" a quem apresenta uma chave roubada conta que
   * o alvo seria válido se estivesse ligado, e "esta pessoa não é sua" confirma
   * quais ids existem em outro lugar.
   *
   * `POST /v1/pay/portal/tickets`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  issuePortalTicket(body: S.PortalTicketBody, options?: RequestOptions): Promise<S.PortalTicketDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/portal/tickets`, body, options });
  }

  /**
   * Publica a chave com que o navegador tokeniza um cartão **novo**.
   *
   * 🚨 **A carteira sai da assinatura, nunca do pedido.** É ela que decide em
   * qual conta conectada a credencial nasce, e é contra essa mesma conta que todo
   * ciclo vai cobrar: um token criado no contexto errado é recusado lá dentro com
   * `Invalid token id`, e a página mostraria recusa do emissor num cartão bom.
   *
   * ⚠️ **Escopo `manage`, embora a chave seja publicável**: pedi-la só faz
   * sentido antes de uma escrita, e responder a qualquer sessão diria a quem só
   * tem leitura qual adquirente o lojista usa.
   *
   * `GET /v1/pay/public/portal/subscriptions/{id}/card-key` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  portalSubscriptionCardKey(id: string, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.CheckoutCardKeyDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/card-key`, auth: false, options });
  }

  /**
   * Passo 1 da entrada por posse: manda o código ao e-mail do **cadastro**.
   *
   * O handoff só existe quando o backend do lojista está de
   * pé e tem a pessoa logada na loja dele. Fora disso o assinante não tem porta
   * nenhuma: é ele quem paga a assinatura todo mês e é ele quem não consegue
   * cancelá-la. Esta é a porta dele.
   *
   * 🚨 **O código vai ao endereço do cadastro, e nunca ao que foi digitado.**
   * Mandá-lo ao valor do corpo deixaria qualquer um receber o próprio desafio e
   * entrar como outra pessoa.
   *
   * `POST /v1/pay/public/portal/access` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  requestPortalAccess(body: S.PortalAccessBody, options?: RequestOptions): Promise<S.PortalAccessChallengeDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/access`, body, auth: false, options });
  }

  /**
   * O assinante pede para sair.
   *
   * ⚠️ **Não encerra agora**: vale na próxima emissão, e até lá ele usa o que já
   * pagou. A resposta traz a assinatura já atualizada, com
   * `cancellation_effective_on` preenchido - sem isso a tela mostraria `active` a
   * quem acabou de cancelar, e ele cancelaria de novo.
   *
   * `POST /v1/pay/public/portal/subscriptions/{id}/cancellation` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  requestPortalCancellation(id: string, body: S.PortalCancellationBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalSubscriptionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/cancellation`, body, auth: false, options });
  }

  /**
   * Passo 1 da troca de e-mail ou telefone: manda o código ao canal **antigo**.
   *
   * 🚨 **O código nunca vai para o `new_value`.** Mandá-lo ao endereço que a
   * pessoa acabou de digitar seria pedir ao atacante que confirmasse o próprio
   * endereço: o controle deixaria de existir mantendo toda a aparência de
   * existir.
   *
   * `POST /v1/pay/public/portal/contact/step-up` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  requestPortalContactChange(body: S.PortalContactChangeBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalContactChallengeDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/public/portal/contact/step-up`, body, auth: false, options });
  }

  /**
   * Ele mudou de ideia antes da data.
   *
   * Desfaz o pedido de cancelamento enquanto a assinatura ainda está no ar, e
   * devolve a assinatura já sem ele. Depois da data não há o que desfazer: a
   * resposta é `subscription_change_rejected`, e não um segundo cancelamento.
   *
   * `DELETE /v1/pay/public/portal/subscriptions/{id}/cancellation` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  revokePortalCancellation(id: string, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalSubscriptionDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/cancellation`, auth: false, options });
  }

  /**
   * Liga ou desliga o portal deste tenant.
   *
   * ⚠️ **Desligado por padrão, e a razão é o alcance**: tenant que não ligou não
   * tem superfície. O aviso de risco na tela de ativação **não transfere risco**:
   * se vazar dado de assinante, quem responde é a plataforma, com aviso lido ou
   * não.
   *
   * `PUT /v1/pay/portal/settings`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setPortalSettings(body: S.PortalSettingsBody, options?: RequestOptions): Promise<S.PortalSettingsDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/portal/settings`, body, options });
  }

  /**
   * Outro meio, ou outro cartão salvo dele, passa a pagar os próximos ciclos.
   *
   * ⚠️ **Em `card`, escolhe entre os cartões que já existem** (os mesmos que
   * saem na conta): cartão novo é o `POST.../cards`, que guarda e já aponta.
   *
   * `PUT /v1/pay/public/portal/subscriptions/{id}/payment-method` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  setPortalSubscriptionPaymentMethod(id: string, body: S.PortalSubscriptionPaymentMethodBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalSubscriptionDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/payment-method`, body, auth: false, options });
  }

  /**
   * Liga ou desliga o lembrete de pagamento da assinatura, por canal.
   *
   * ⚠️ **Só os canais que vierem no corpo mudam**: corpo vazio devolve a
   * assinatura como está, sem aviso nem trilha.
   *
   * `PUT /v1/pay/public/portal/subscriptions/{id}/reminders` (public route, sent without credentials)
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  setPortalSubscriptionReminders(id: string, body: S.PortalSubscriptionRemindersBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalSubscriptionDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/public/portal/subscriptions/${seg(id)}/reminders`, body, auth: false, options });
  }

  /**
   * Corrige **nome e endereço** do cadastro.
   *
   * ⚠️ **Sem código, e a diferença para a troca de canal é deliberada**: nome e
   * endereço não dão acesso a nada, e exigir um código para corrigir o número da
   * casa treinaria o assinante a pedir e digitar códigos por rotina, que é o
   * hábito de que o golpe do `T9` precisa.
   *
   * 🚨 **Mas entra na trilha e avisa o e-mail do cadastro**: o nome é
   * o que o atendimento usa para reconhecer a pessoa, e o endereço é para onde a
   * mercadoria vai. Quem entrou como se fosse outra pessoa muda os dois antes de
   * fazer o resto, e o aviso é o que devolve ao titular a chance de perceber.
   *
   * `PUT /v1/pay/public/portal/profile` (public route, sent without credentials)
   *
   * @param body Request body.
   * @param options Per-call overrides. Headers of this route: `x-portal-session` (required).
   */
  updatePortalProfile(body: S.PortalProfileBody, options: RequestOptions & { headers: { "x-portal-session": string } }): Promise<S.PortalPersonDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/public/portal/profile`, body, auth: false, options });
  }
}

