/** Routes tagged `pay · profit-centers`. */
export class PayProfitCentersResource extends Resource {
  /**
   * Cria um centro.
   *
   * O código é único por organização e não muda depois. Numa sessão do tenant
   * inteiro, sem `organization_id`, o centro nasce compartilhado por todas as
   * organizações. O pai precisa estar no mesmo escopo.
   *
   * `POST /v1/pay/profit-centers`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  create(body: S.ProfitCenterCreateBody, options?: RequestOptions): Promise<S.ProfitCenterDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/profit-centers`, body, options });
  }

  /**
   * Apaga (soft-delete); o passado continua atribuído ao centro.
   *
   * Com filho ativo a resposta é 412: apague ou mova os filhos antes. Os
   * lançamentos já atribuídos seguem contando para o centro no resultado.
   *
   * `DELETE /v1/pay/profit-centers/{id}`
   *
   * @param id Centro de lucro
   * @param options Per-call overrides.
   */
  deleteOne(id: string, options?: RequestOptions): Promise<S.ProfitCenterDeletedDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/profit-centers/${seg(id)}`, options });
  }

  /**
   * Centro de lucro de origem de um centro de custo.
   *
   * `profit_center` ausente quando o centro de custo não tem origem.
   *
   * `GET /v1/pay/cost-centers/{id}/profit-center`
   *
   * @param id Centro de custo
   * @param options Per-call overrides.
   */
  getCostCenterOrigin(id: string, options?: RequestOptions): Promise<S.ProfitCenterAssignmentDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/cost-centers/${seg(id)}/profit-center`, options });
  }

  /**
   * Lê um centro.
   *
   * Centro fora da vista da sessão responde 404, como se não existisse. O
   * apagado continua legível.
   *
   * `GET /v1/pay/profit-centers/{id}`
   *
   * @param id Centro de lucro
   * @param options Per-call overrides.
   */
  getOne(id: string, options?: RequestOptions): Promise<S.ProfitCenterDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/profit-centers/${seg(id)}`, options });
  }

  /**
   * Centro de lucro de um título a receber.
   *
   * Mostra só o vínculo direto do título; ausente quando ele segue o centro de
   * custo.
   *
   * `GET /v1/pay/receivables/{id}/profit-center`
   *
   * @param id Título a receber
   * @param options Per-call overrides.
   */
  getReceivableCenter(id: string, options?: RequestOptions): Promise<S.ProfitCenterAssignmentDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/receivables/${seg(id)}/profit-center`, options });
  }

  /**
   * O que o centro junta: centros de custo de origem e títulos ligados.
   *
   * Serve para conferir o alcance de uma mudança antes de apagar ou de trocar
   * vínculos: lista os centros de custo que têm este como origem e conta os
   * títulos a receber ligados direto a ele.
   *
   * `GET /v1/pay/profit-centers/{id}/links`
   *
   * @param id Centro de lucro
   * @param options Per-call overrides.
   */
  links(id: string, options?: RequestOptions): Promise<S.ProfitCenterLinksDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/profit-centers/${seg(id)}/links`, options });
  }

  /**
   * Lista os centros do escopo (os da organização e os compartilhados).
   *
   * Sessão presa a uma organização vê os dela e os compartilhados do tenant;
   * com `org_scope=subtree` entram as organizações abaixo. Apagados só com
   * `include_deleted`.
   *
   * `GET /v1/pay/profit-centers`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  list(query?: PayProfitCentersListQuery, options?: RequestOptions): Promise<S.ProfitCenterPageDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/profit-centers`, query, options });
  }

  /**
   * Iterates every item of `list`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/profit-centers`
   */
  listAll(query?: PayProfitCentersListQuery, options?: RequestOptions): Paginator<NonNullable<S.ProfitCenterPageDto["items"]>[number], S.ProfitCenterPageDto> {
    return new Paginator((page_token) => this.list({ ...query, page_token } as PayProfitCentersListQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * DRE aberta por centro de lucro, numa janela de competência de até 366 dias.
   *
   * Cada centro traz o que foi atribuído direto a ele e o total com os
   * descendentes. O vínculo do título a receber vence o do centro de custo, o
   * que não tem vínculo cai em `unassigned`, e `grand_total` fecha com a DRE do
   * período.
   *
   * `GET /v1/pay/profit-centers/result`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  result(query: PayProfitCentersResultQuery, options?: RequestOptions): Promise<S.ProfitCenterResultDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/profit-centers/result`, query, options });
  }

  /**
   * Troca o centro de lucro de origem de um centro de custo. Vale para o
   * passado: os lançamentos já feitos com o centro de custo passam a contar
   * para o centro de lucro novo.
   *
   * Corpo com `profit_center_id` nulo tira o vínculo. O centro de lucro precisa
   * estar ativo e no escopo da organização do centro de custo.
   *
   * `PUT /v1/pay/cost-centers/{id}/profit-center`
   *
   * @param id Centro de custo
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setCostCenterOrigin(id: string, body: S.ProfitCenterAssignBody, options?: RequestOptions): Promise<S.ProfitCenterAssignmentDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/cost-centers/${seg(id)}/profit-center`, body, options });
  }

  /**
   * Liga um título a receber a um centro de lucro; vence o vínculo do centro
   * de custo e vale para a baixa já feita.
   *
   * Corpo com `profit_center_id` nulo tira o vínculo direto, e o título volta a
   * seguir o centro de custo. O centro precisa estar ativo e no escopo do título.
   *
   * `PUT /v1/pay/receivables/{id}/profit-center`
   *
   * @param id Título a receber
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setReceivableCenter(id: string, body: S.ProfitCenterAssignBody, options?: RequestOptions): Promise<S.ProfitCenterAssignmentDto> {
    return this._http.request({ method: 'PUT', path: `/v1/pay/receivables/${seg(id)}/profit-center`, body, options });
  }

  /**
   * A árvore inteira do escopo, em ordem de código.
   *
   * Sem paginação: devolve todos os centros do escopo de uma vez para a tela
   * montar a árvore. Acima de 5000 centros a resposta é 412.
   *
   * `GET /v1/pay/profit-centers/tree`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  tree(query?: PayProfitCentersTreeQuery, options?: RequestOptions): Promise<S.ProfitCenterTreeDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/profit-centers/tree`, query, options });
  }

  /**
   * Renomeia ou troca o ID personalizado (o código é imutável).
   *
   * Campo ausente fica como está; `external_code` vazio limpa. Centro
   * compartilhado só muda numa sessão do tenant inteiro.
   *
   * `PATCH /v1/pay/profit-centers/{id}`
   *
   * @param id Centro de lucro
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateOne(id: string, body: S.ProfitCenterUpdateBody, options?: RequestOptions): Promise<S.ProfitCenterDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/profit-centers/${seg(id)}`, body, options });
  }
}

