/** Routes tagged `pay · recorrência`. */
export class PayRecorrenciaResource extends Resource {
  /**
   * Move a assinatura para outro plano.
   *
   * A troca vale do **próximo ciclo**: o `subscription_id`, a vigência e a data
   * da próxima cobrança são preservados, e ciclo já emitido não é reescrito - ele
   * guarda o valor congelado do plano de quando saiu.
   *
   * É a alternativa ao contorno de cancelar e reassinar, que perde a
   * continuidade da assinatura e, dependendo do dia, cobra dois ciclos ou nenhum.
   *
   * `PATCH /v1/pay/recurrence/subscriptions/{id}/plan`
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  changeSubscriptionPlan(id: string, body: S.ChangeSubscriptionPlanBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/plan`, body, options });
  }

  /**
   * Cria um plano de recorrência.
   *
   * O plano guarda o **o quê**: valor, moeda, periodicidade e as regras do ciclo.
   * Quem decide **quando** o ciclo vence é o agendador, que só olha data e nunca
   * regra de negócio.
   *
   * A separação é o desenho: mover a decisão de valor para o agendador faria o
   * serviço temporal precisar entender cobrança, e mover a decisão de data para o
   * plano faria cada plano reimplementar calendário.
   *
   * `POST /v1/pay/recurrence/plans`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createPlan(body: S.CreateRecurrencePlanBody, options?: RequestOptions): Promise<S.RecurrencePlanDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/recurrence/plans`, body, options });
  }

  /**
   * Lista planos de recorrência.
   *
   * Lista os planos de recorrência do tenant, paginados por cursor opaco.
   *
   * `GET /v1/pay/recurrence/plans`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listPlans(query?: PayRecorrenciaListPlansQuery, options?: RequestOptions): Promise<S.RecurrencePlansListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/recurrence/plans`, query, options });
  }

  /**
   * Iterates every item of `listPlans`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/recurrence/plans`
   */
  listPlansAll(query?: PayRecorrenciaListPlansQuery, options?: RequestOptions): Paginator<NonNullable<S.RecurrencePlansListDto["items"]>[number], S.RecurrencePlansListDto> {
    return new Paginator((page_token) => this.listPlans({ ...query, page_token } as PayRecorrenciaListPlansQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Lista assinaturas.
   *
   * Lista as assinaturas com paginação por cursor opaco.
   *
   * É por aqui que se vê quem está em qual plano e em que ponto do ciclo cada um
   * está.
   *
   * `GET /v1/pay/recurrence/subscriptions`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listSubscriptions(query?: PayRecorrenciaListSubscriptionsQuery, options?: RequestOptions): Promise<S.SubscriptionsListDto> {
    return this._http.request({ method: 'GET', path: `/v1/pay/recurrence/subscriptions`, query, options });
  }

  /**
   * Iterates every item of `listSubscriptions`, following `next_page_token` page after page.
   *
   * `GET /v1/pay/recurrence/subscriptions`
   */
  listSubscriptionsAll(query?: PayRecorrenciaListSubscriptionsQuery, options?: RequestOptions): Paginator<NonNullable<S.SubscriptionsListDto["items"]>[number], S.SubscriptionsListDto> {
    return new Paginator((page_token) => this.listSubscriptions({ ...query, page_token } as PayRecorrenciaListSubscriptionsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Registra o pedido de cancelamento do assinante.
   *
   * A assinatura **continua ativa** até a próxima emissão: é o período que o
   * cliente já pagou, e é a janela em que ele pode voltar atrás. No dia em que o
   * ciclo nasceria, o lote encerra o contrato sem cobrar e publica
   * `pay.subscription.canceled`.
   *
   * Idempotente: pedir duas vezes devolve a mesma data e não manda um segundo
   * aviso.
   *
   * `POST /v1/pay/recurrence/subscriptions/{id}/cancellation`
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  requestSubscriptionCancellation(id: string, body: S.RequestCancellationBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/cancellation`, body, options });
  }

  /**
   * Desfaz o pedido de cancelamento - o cliente reativou a tempo.
   *
   * Só vale enquanto a data de efeito não chegou. Depois dela a assinatura está
   * `canceled`, e voltar é assinar de novo.
   *
   * `DELETE /v1/pay/recurrence/subscriptions/{id}/cancellation`
   *
   * @param id Snowflake da assinatura
   * @param options Per-call overrides.
   */
  revokeSubscriptionCancellation(id: string, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'DELETE', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/cancellation`, options });
  }

  /**
   * Troca a régua de aviso de um plano vivo.
   *
   * Quais avisos saem (emissão, antes, no dia, depois) e a quantos dias do
   * vencimento. É a única mudança que o plano aceita além do status: preço e
   * calendário seguem congelados. Vale para todos os assinantes
   * do plano, da próxima varredura em diante.
   *
   * `PATCH /v1/pay/recurrence/plans/{id}/reminders`
   *
   * @param id Snowflake do plano
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setPlanReminders(id: string, body: S.SetPlanRemindersBody, options?: RequestOptions): Promise<S.RecurrencePlanDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/recurrence/plans/${seg(id)}/reminders`, body, options });
  }

  /**
   * Troca o método que paga os ciclos de uma assinatura.
   *
   * Generaliza a troca de cartão: num plano de vários métodos, quem
   * entrou no boleto passa ao PIX ou ao cartão sem cancelar e reassinar. Vale do
   * próximo ciclo; o título já emitido segue com o instrumento dele. Continua
   * sendo a saída para o cartão que venceu, foi perdido ou foi trocado pelo
   * banco: é `card` com outro cartão.
   *
   * `PATCH /v1/pay/recurrence/subscriptions/{id}/payment-method`
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setSubscriptionPaymentMethod(id: string, body: S.SetSubscriptionPaymentMethodBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/payment-method`, body, options });
  }

  /**
   * Grava em quais canais o assinante aceita lembrete de pagamento, a pedido
   * dele.
   *
   * Vale para os quatro avisos de lembrar de pagar (emissão, antes, no dia e
   * depois). Falha de cobrança e pagamento confirmado saem sempre. O evento
   * continua saindo para o webhook: quem obedece é a hidratação, que entrega o
   * contato do canal desligado vazio.
   *
   * `PATCH /v1/pay/recurrence/subscriptions/{id}/reminders`
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setSubscriptionReminders(id: string, body: S.SetSubscriptionRemindersBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/reminders`, body, options });
  }

  /**
   * Pausa, retoma ou cancela uma assinatura.
   *
   * Cancelar é **terminal**: uma assinatura cancelada não volta a emitir ciclo,
   * e reativar exige assinar de novo.
   *
   * `PATCH /v1/pay/recurrence/subscriptions/{id}/status`
   *
   * @param id Snowflake da assinatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setSubscriptionStatus(id: string, body: S.SetSubscriptionStatusBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'PATCH', path: `/v1/pay/recurrence/subscriptions/${seg(id)}/status`, body, options });
  }

  /**
   * Simula a agenda de cobrança de uma adesão.
   *
   * Responde "se alguém assinar neste dia, quando e quanto paga": o que a adesão
   * cobra no ato e os próximos ciclos, com faturamento, período coberto,
   * vencimento já ajustado para dia útil e valor. Serve a um plano existente ou
   * a um rascunho, para o lojista ver a conta antes de criar o plano.
   *
   * Não cria nada. A conta é a mesma que a emissão faz, então o que a tela
   * mostra é o que o assinante recebe. Com `trial_coupon_code`, os dias do cupom
   * entram no teste pelas mesmas recusas da adesão, sem consumir nada; o teto
   * por documento só é conferido quando `iam_person_id` vem junto. Cupom de
   * desconto ainda não entra: ele é decidido ciclo a ciclo na emissão.
   *
   * `POST /v1/pay/recurrence/plans/simulate`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  simulatePlanSchedule(body: S.SimulatePlanScheduleBody, options?: RequestOptions): Promise<S.PlanScheduleSimulationDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/recurrence/plans/simulate`, body, options });
  }

  /**
   * Adere um pagador a um plano de recorrência (cria a assinatura).
   *
   * Cria a assinatura, que é o vínculo entre um pagador e um plano.
   *
   * É a assinatura, não o plano, que gera cobrança: o plano é o molde, e cada
   * assinatura tem o próprio ciclo, com data de início e situação próprias.
   *
   * `POST /v1/pay/recurrence/subscriptions`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  subscribe(body: S.SubscribeBody, options?: RequestOptions): Promise<S.SubscriptionDto> {
    return this._http.request({ method: 'POST', path: `/v1/pay/recurrence/subscriptions`, body, options });
  }
}

